import{_ as e,o as r,c as i,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Постоянная совместная колония","description":"","frontmatter":{"pageId":"players/coop","contentRevision":1},"headers":[],"relativePath":"ru/players/coop.md","filePath":"ru/players/coop.md"}'),t={name:"ru/players/coop.md"};function o(s,a,n,c,d,p){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="постоянная-совместная-колония" tabindex="-1">Постоянная совместная колония <a class="header-anchor" href="#постоянная-совместная-колония" aria-label="Permalink to &quot;Постоянная совместная колония&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Хозяин открывает <strong>Совместная колония</strong> под чатом и приглашает партнёра.</li><li>Партнёр открывает то же окно, обновляет список и принимает.</li><li>Хозяин назначает свободных колонистов домашней карты.</li><li>Партнёр из своей домашней колонии нажимает <strong>Войти в колонию</strong>. Его дом сохраняется до загрузки зеркала.</li><li>Партнёр управляет назначенными пешками, включая работу, расписание, экипировку и бой; хозяин продолжает игру и пишет единственный канонический сейв.</li></ol><p>Членство переживает перезапуск. Изменение назначений или отзыв завершает текущую сессию. Для завершения партнёр выходит домой.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Один партнёр одновременно, до 8 приглашений/участников и 32 пешек. Хозяин должен быть онлайн дома. Кошелёк, отправка вещей и админ-права не передаются. Reset удаляет членство; archive/restore сохраняет; rollback сохраняет членство, но очищает назначения. Пешки хозяина не возвращаются партнёру почтой.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./../admins/administration">Панель и модерация</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',9)])])}const _=e(t,[["render",o]]);export{u as __pageData,_ as default};
